INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO-071','beginner','Serwis i diagnostyka / Service & Diagnostics','Urządzenia peryferyjne','','description: Awaria myszy lub dysku zewnętrznego nie musi oznaczać awarii komputera. step: Porównaj inne bezpieczne urządzenie i port; nie podłączaj uszkodzonego przewodu.','','',''),
('beginner:ZERO-072','beginner','Dyski i dane / Storage & Data','Kopia danych przed serwisem','','description: Serwis może wymagać testów lub wymiany dysku. step: Jeśli urządzenie działa bezpiecznie, wykonaj i zweryfikuj kopię ważnych plików.','','',''),
('beginner:ZERO-073','beginner','Serwis i diagnostyka / Service & Diagnostics','Dokumentacja modelu','','description: Instrukcje dla podobnych komputerów mogą różnić się ważnymi szczegółami. step: Odczytaj dokładne oznaczenie modelu i szukaj dokumentacji producenta.','','',''),
('beginner:ZERO-074','beginner','Serwis i diagnostyka / Service & Diagnostics','Gwarancja i rękojmia','','description: Niektóre czynności mogą wpływać na warunki obsługi urządzenia. step: Sprawdź dokumenty zakupu i zasady producenta przed rozbieraniem sprzętu.','','',''),
('beginner:ZERO-075','beginner','Serwis i diagnostyka / Service & Diagnostics','Plan kopii zapasowych 3-2-1','','description: Kilka kopii w różnych miejscach ogranicza ryzyko utraty danych. step: Ustal, które pliki są ważne, i sprawdź możliwość odtworzenia jednej kopii.','','',''),
('beginner:ZERO-076','beginner','Dyski i dane / Storage & Data','Przywracanie plików z kopii','','description: Sama obecność archiwum nie gwarantuje, że da się odzyskać pliki. step: Przetestuj odtworzenie pojedynczego pliku do osobnego folderu.','','',''),
('beginner:ZERO-077','beginner','Dyski i dane / Storage & Data','Dysk zewnętrzny nie jest wykrywany','','description: Problem może dotyczyć przewodu, portu, zasilania lub samego nośnika. step: Porównaj sprawny kabel; jeśli dysk wydaje nietypowe dźwięki, zakończ próby.','','',''),
('beginner:ZERO-078','beginner','Serwis i diagnostyka / Service & Diagnostics','Pendrive prosi o formatowanie','','description: Komunikat nie oznacza, że formatowanie jest bezpieczne dla danych. step: Nie zatwierdzaj formatowania, jeśli potrzebujesz znajdujących się tam plików.','','',''),
('beginner:ZERO-079','beginner','Chłodzenie / Cooling','Temperatura procesora i GPU','','description: Temperaturę trzeba interpretować w kontekście modelu i obciążenia. step: Sprawdź wartości narzędziem diagnostycznym i porównaj z zaleceniami producenta.','','',''),
('beginner:ZERO-080','beginner','Chłodzenie / Cooling','Hałas wentylatora','','description: Głośna praca może wynikać z obciążenia lub ograniczonego przepływu powietrza. step: Sprawdź obciążenie systemu i drożność wlotów bez rozbierania zasilacza.','','',''),
('beginner:ZERO-081','beginner','Serwis i diagnostyka / Service & Diagnostics','Komputer zawiesza się losowo','','description: Przyczyny mogą dotyczyć pamięci, dysku, temperatur lub oprogramowania. step: Zanotuj okoliczności zawieszenia i zabezpiecz ważne pliki.','','',''),
('beginner:ZERO-082','beginner','BIOS i rozruch / BIOS & Boot','Aplikacja nie uruchamia się','','description: Błąd jednej aplikacji nie oznacza awarii całego komputera. step: Zapisz komunikat i sprawdź oficjalne wymagania oraz aktualizacje aplikacji.','','',''),
('beginner:ZERO-083','beginner','BIOS i rozruch / BIOS & Boot','Programy startowe','','description: Duża liczba programów uruchamianych z systemem może spowolnić start. step: Przejrzyj listę startową; wyłączaj tylko rozpoznane programy.','','',''),
('beginner:ZERO-084','beginner','Dyski i dane / Storage & Data','Integralność plików systemowych','','description: Uszkodzone pliki mogą powodować błędy, lecz objawy mają też inne przyczyny. step: Zrób kopię danych i skorzystaj z oficjalnych narzędzi naprawczych systemu.','','',''),
('beginner:ZERO-085','beginner','System i sterowniki / System & Drivers','Miejsce na aktualizacje','','description: Brak wolnej przestrzeni może przerwać aktualizację lub instalację. step: Sprawdź dostępne miejsce i usuń tylko własne, zbędne pliki po wykonaniu kopii.','','',''),
('beginner:ZERO-086','beginner','Serwis i diagnostyka / Service & Diagnostics','Konto użytkownika i profil','','description: Problem ograniczony do jednego profilu może wynikać z jego ustawień. step: Porównaj działanie na innym własnym koncie, nie usuwając starego profilu.','','',''),
('beginner:ZERO-087','beginner','System i sterowniki / System & Drivers','Data i godzina systemowa','','description: Nieprawidłowy czas może utrudniać dostęp do stron i aktualizacje. step: Sprawdź strefę czasową oraz automatyczną synchronizację.','','',''),
('beginner:ZERO-088','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Certyfikaty i bezpieczne strony','','description: Błąd certyfikatu bywa związany z datą, siecią albo samą stroną. step: Sprawdź datę systemową; nie ignoruj ostrzeżeń bezpieczeństwa.','','',''),
('beginner:ZERO-089','beginner','Serwis i diagnostyka / Service & Diagnostics','Adres IP i DHCP','','description: Brak poprawnego adresu może uniemożliwić działanie sieci. step: Sprawdź stan połączenia i porównaj inne urządzenie w tej samej sieci.','','',''),
('beginner:ZERO-090','beginner','Sieć i internet / Network','VPN i połączenie internetowe','','description: VPN może wpływać na dostęp do wybranych stron i usług. step: Porównaj działanie bez VPN, jeśli możesz to zrobić zgodnie z zasadami swojej sieci.','','',''),
('beginner:ZERO-091','beginner','Sieć i internet / Network','Prędkość internetu a Wi-Fi','','description: Wynik testu zależy od łącza, sieci bezprzewodowej i obciążenia. step: Porównaj pomiar na innym urządzeniu oraz, jeśli możliwe, przez Ethernet.','','',''),
('beginner:ZERO-092','beginner','Obraz i ekran / Display','Zakłócenia obrazu i artefakty','','description: Artefakty mogą pochodzić z monitora, kabla, sterownika lub karty graficznej. step: Sprawdź inny kabel i zanotuj, czy problem widać już przed startem systemu.','','',''),
('beginner:ZERO-093','beginner','Obraz i ekran / Display','Rozdzielczość i odświeżanie monitora','','description: Nieobsługiwany tryb może powodować brak obrazu lub migotanie. step: Wybierz ustawienia obsługiwane przez monitor i używane złącze.','','',''),
('beginner:ZERO-094','beginner','Zasilanie / Power','Bateria CMOS i utrata ustawień','','description: Utrata daty lub ustawień może mieć związek z podtrzymaniem zegara. step: Sprawdź objawy i instrukcję modelu; nie wymieniaj elementów pod napięciem.','','',''),
('beginner:ZERO-095','beginner','Peryferia / Peripherals','Ładowanie przez USB-C','','description: Port USB-C i ładowarka muszą obsługiwać odpowiedni standard oraz moc. step: Porównaj dokumentację laptopa, przewodu i zasilacza.','','',''),
('beginner:ZERO-096','beginner','Serwis i diagnostyka / Service & Diagnostics','Śrubki, zatrzaski i instrukcja serwisowa','','description: Ukryte mocowania łatwo uszkodzić przy otwieraniu obudowy. step: Przed demontażem odłącz zasilanie i sprawdź instrukcję dokładnego modelu.','','',''),
('beginner:ZERO-097','beginner','Serwis i diagnostyka / Service & Diagnostics','Przekazanie sprzętu do serwisu','','description: Dokładny opis usterki ułatwia diagnozę i ogranicza zbędne próby. step: Zapisz objawy, wykonane testy i stan kopii danych; nie podawaj haseł w notatce.','','',''),
('beginner:ZERO-098','beginner','Serwis i diagnostyka / Service & Diagnostics','Komunikaty i kontrolki diagnostyczne','','description: Kolor diody i sekwencja mignięć zależą od producenta. step: Zapisz dokładną sekwencję i sprawdź instrukcję danego modelu.','','',''),
('beginner:ZERO-099','beginner','BIOS i rozruch / BIOS & Boot','Sygnały dźwiękowe POST','','description: Podobny dźwięk może oznaczać różne usterki w różnych płytach. step: Zanotuj liczbę i długość sygnałów; porównaj je z dokumentacją.','','',''),
('beginner:ZERO-100','beginner','BIOS i rozruch / BIOS & Boot','Kolejność rozruchu','','description: Komputer może próbować startować z niewłaściwego nośnika. step: Sprawdź listę urządzeń rozruchowych; przed zmianą ustawień zabezpiecz klucz odzyskiwania.','','',''),
('beginner:ZERO-101','beginner','BIOS i rozruch / BIOS & Boot','Tryb UEFI i starszy rozruch','','description: Zmiana trybu startu może uniemożliwić uruchomienie systemu. step: Zapisz bieżącą konfigurację i sprawdź sposób instalacji systemu.','','',''),
('beginner:ZERO-102','beginner','BIOS i rozruch / BIOS & Boot','Secure Boot','','description: Ta funkcja sprawdza zaufanie do oprogramowania startowego. step: Nie wyłączaj jej przypadkowo; najpierw zapisz dokładny komunikat błędu.','','',''),
('beginner:ZERO-103','beginner','BIOS i rozruch / BIOS & Boot','Dysk widoczny w UEFI, niewidoczny w systemie','','description: Wykrycie nośnika przez firmware nie gwarantuje dostępu do jego danych. step: Zabezpiecz istniejące dane; nie inicjuj ani nie formatuj dysku w ciemno.','','',''),
('beginner:ZERO-104','beginner','System i sterowniki / System & Drivers','Pamięć wirtualna','','description: System może korzystać z dysku, gdy brakuje pamięci operacyjnej. step: Sprawdź użycie RAM i wolne miejsce bez usuwania nieznanych plików.','','',''),
('beginner:ZERO-105','beginner','Sprzęt i podzespoły / Hardware','RAM w dwóch kanałach','','description: Rozmieszczenie modułów może wpływać na wydajność. step: Sprawdź zalecane gniazda w instrukcji płyty przed zmianą konfiguracji.','','','');
